const PAT = 'AIRTABLE_PAT_REDACTED';
const BASE_ID = 'appmBaUD39bNFM4QA';
const LOCATIONS_TABLE = 'tbltUIpyKYxotKJN4';
const MENU_TABLE = 'tbltYZZMUsQg5rxPC';
const ORDERS_TABLE = 'tblQkG1DeczNyWsyM';
const LOC_CACHE_TTL  = 6  * 60 * 60 * 1000; // 6h
const MENU_CACHE_TTL = 30 * 60 * 1000;       // 30min

const body    = $input.first().json.body || $input.first().json;
const msgType = body?.message?.type || '';

// ── end-of-call-report: patch Orders record with recording URL + transcript ──
if (msgType === 'end-of-call-report') {
  const callId       = body?.message?.call?.id || '';
  const recordingUrl = body?.message?.artifact?.recordingUrl || '';
  const transcript   = body?.message?.artifact?.transcript   || '';

  if (callId) {
    const formula   = encodeURIComponent('{Call ID}="' + callId + '"');
    const searchRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.airtable.com/v0/' + BASE_ID + '/' + ORDERS_TABLE +
           '?filterByFormula=' + formula + '&maxRecords=1',
      headers: { Authorization: 'Bearer ' + PAT }
    });

    if (searchRes.records && searchRes.records.length > 0) {
      const recId  = searchRes.records[0].id;
      const fields = {};
      if (recordingUrl) fields['fldgEdVyTu9OjeaFY'] = recordingUrl;
      if (transcript)   fields['fldbApN3f2mBSi3Ea'] = transcript;
      if (Object.keys(fields).length > 0) {
        await this.helpers.httpRequest({
          method: 'PATCH',
          url: 'https://api.airtable.com/v0/' + BASE_ID + '/' + ORDERS_TABLE + '/' + recId,
          headers: { Authorization: 'Bearer ' + PAT, 'Content-Type': 'application/json' },
          body: JSON.stringify({ fields })
        });
      }
    }
  }
  return [{ json: {} }];
}

// ── assistant-request / call start: inject locations + live menu prices ──
const cache = $getWorkflowStaticData('global');
const now   = Date.now();

// -- Locations (cached 6h) --
let locRecords;
const locHit = cache['all_active'];
if (locHit && (now - locHit.ts) < LOC_CACHE_TTL) {
  locRecords = locHit.data;
} else {
  const url = 'https://api.airtable.com/v0/' + BASE_ID + '/' + LOCATIONS_TABLE +
    '?filterByFormula=' + encodeURIComponent('{Active}=TRUE()');
  const res = await this.helpers.httpRequest({ method: 'GET', url, headers: { Authorization: 'Bearer ' + PAT } });
  locRecords = res.records || [];
  cache['all_active'] = { data: locRecords, ts: now };
}

const byState = {};
locRecords.forEach(r => {
  const f     = r.fields;
  const state = f['State'] || 'Other';
  if (!byState[state]) byState[state] = [];
  let line = (f['Location Name'] || '') + ': ' + (f['Address'] || '') + ', ' + (f['City'] || '');
  if (f['Phone']) line += ' (' + f['Phone'] + ')';
  byState[state].push(line);
});

const locText = Object.keys(byState).sort()
  .map(s => s + ':\n' + byState[s].join('\n'))
  .join('\n\n');

// -- Menu prices (cached 30min) --
let menuRecords;
const menuHit = cache['menu_prices'];
if (menuHit && (now - menuHit.ts) < MENU_CACHE_TTL) {
  menuRecords = menuHit.data;
} else {
  let all = [];
  let offset;
  do {
    const url = 'https://api.airtable.com/v0/' + BASE_ID + '/' + MENU_TABLE +
      '?fields[]=Item%20Name&fields[]=Price&fields[]=Category&pageSize=100&filterByFormula=%7BAvailable%7D%3DTRUE()' +
      (offset ? '&offset=' + offset : '');
    const res = await this.helpers.httpRequest({ method: 'GET', url, headers: { Authorization: 'Bearer ' + PAT } });
    all    = all.concat(res.records || []);
    offset = res.offset;
  } while (offset);
  menuRecords = all;
  cache['menu_prices'] = { data: menuRecords, ts: now };
}

const byCategory = {};
menuRecords.forEach(r => {
  const name  = r.fields['Item Name'] || '';
  const price = Number(r.fields['Price']);
  const cat   = r.fields['Category'] || 'Other';
  if (!name || !price) return; // skip items with no price or $0
  if (!byCategory[cat]) byCategory[cat] = [];
  byCategory[cat].push(name + ' $' + price.toFixed(2));
});

const menuText = Object.keys(byCategory).sort()
  .map(cat => cat + ': ' + byCategory[cat].join(' | '))
  .join('\n');

const contextContent =
  '## STORE LOCATIONS\n\n' + locText +
  '\n\n## CURRENT MENU PRICES (live from Airtable — always use these, never guess)\n\n' + menuText;

return [{ json: {
  messageResponse: {
    assistant: {
      model: {
        messages: [{ role: 'system', content: contextContent }]
      }
    }
  }
} }];
